def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find the first diagonal pair of matching non-background cells.
    pair = None
    for r in range(h - 1):
        for c in range(w):
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r][c] != bg and grid[r][c] == grid[r + 1][nc]:
                    pair = (r, c, dc, grid[r][c])
                    break
            if pair:
                break
        if pair:
            break

    if pair:
        r, c, dc, color = pair
        # Extend outward from the earlier (upper) cell, away from its pair.
        dr, dc = -1, -dc
        r += dr
        c += dc
        while 0 <= r < h and 0 <= c < w:
            if out[r][c] == bg:
                out[r][c] = color
            r += dr
            c += dc

    return out
